using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using LighthouseKeepers.Core;
namespace LighthouseKeepers.WatchDemo {
 public sealed class StoryDressing:MonoBehaviour {
  WatchDemoController watch;M2StationParts parts;WatchBeacon beacon;Material glass,windowGlass,ink,paper,oilskin;Renderer core;readonly List<Material> owned=new();MaterialPropertyBlock block;Mesh ropeMesh;
  public static void Create(WatchDemoController w){if(!VisualPassSettings.Current||!VisualPassSettings.Current.setDressing)return;var p=w.gameObject.AddComponent<StoryDressing>();p.watch=w;}
  void Start(){parts=gameObject.AddComponent<M2StationParts>();parts.Initialize();beacon=FindAnyObjectByType<WatchBeacon>();block=new MaterialPropertyBlock();glass=new Material(Resources.Load<Shader>("BeaconGlass"));owned.Add(glass);glass.SetColor("_BaseColor",new Color(.65f,.78f,.80f));foreach(var lens in beacon.lenses)lens.sharedMaterial=glass;windowGlass=new Material(glass);windowGlass.SetFloat("_Window",1);owned.Add(windowGlass);
   foreach(var r in FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None))if((r.name.Contains("Glaz")||r.name.Contains("Glass"))&&r.transform.position.y>10){if(r.transform.root.name.Contains("Player"))continue;r.sharedMaterial=windowGlass;}
   // Rain panes sit in the shell window recesses; no collision or new openings.
   foreach(var point in new[]{new Vector2(60,1.65f),new Vector2(60,4.95f),new Vector2(45,8.25f),new Vector2(315,8.25f)}){float a=point.x*Mathf.Deg2Rad;var pane=parts.Part("Rain on recessed window",transform,new Vector3(Mathf.Sin(a)*3.72f,point.y,Mathf.Cos(a)*3.72f),new Vector3(.65f,.90f,.008f),windowGlass);pane.transform.rotation=Quaternion.Euler(0,point.x,0);}
   var bulb=parts.Part("Amber lamp inside glass lens",beacon.rotor,new Vector3(0,.44f,0),new Vector3(.16f,.64f,.16f),parts.Brass,PrimitiveType.Capsule);core=bulb.GetComponent<Renderer>();
   paper=Mat("Logbook paper",new Color(.58f,.49f,.30f));ink=Mat("Aged photograph",new Color(.12f,.11f,.08f));oilskin=Mat("Keeper oilskin",new Color(.43f,.30f,.08f));
   var desk=GameObject.Find("Wrench table top");if(desk){var bounds=desk.GetComponent<Renderer>().bounds;var p=new Vector3(bounds.center.x,bounds.max.y+.018f,bounds.max.z-.22f);var book=M2StationParts.Root("Previous keeper open logbook",transform,Vector3.zero);book.position=p;book.rotation=Quaternion.Euler(0,90,0);parts.Part("Leather logbook cover",book,Vector3.zero,new Vector3(.34f,.02f,.25f),parts.Dark);parts.Part("Open logbook paper",book,new Vector3(0,.013f,0),new Vector3(.32f,.008f,.23f),paper);var text=parts.Text("Previous keeper entry",KeeperStrings.Get("story.logbook"),book,new Vector3(0,.020f,0),.0014f);text.transform.localRotation=Quaternion.Euler(90,0,0);text.color=new Color(.08f,.07f,.05f);}
   var coat=M2StationParts.Root("Oilskin on wall hook",transform,new Vector3(3.36f,1.4f,-9.7f));coat.rotation=Quaternion.Euler(0,-90,0);parts.Part("Oilskin coat body",coat,Vector3.zero,new Vector3(.4f,.65f,.10f),oilskin,PrimitiveType.Capsule);foreach(float x in new[]{-.25f,.25f}){var sleeve=parts.Part("Hanging coat sleeve",coat,new Vector3(x,.08f,0),new Vector3(.12f,.45f,.12f),oilskin,PrimitiveType.Capsule);sleeve.transform.localRotation=Quaternion.Euler(0,0,-x*45);}parts.Part("Brass coat hook",coat,new Vector3(0,.48f,-.02f),new Vector3(.035f,.10f,.08f),parts.Brass);
   var photo=M2StationParts.Root("Old keeper photograph",transform,new Vector3(-3.43f,1.55f,-9.9f));photo.rotation=Quaternion.Euler(0,90,0);parts.Part("Photograph frame",photo,Vector3.zero,new Vector3(.28f,.34f,.03f),Resources.Load<Material>("VisualMaterials/Wood"));parts.Part("Sepia photograph paper",photo,new Vector3(0,0,.02f),new Vector3(.23f,.29f,.008f),paper);parts.Part("Photograph head silhouette",photo,new Vector3(0,.055f,.027f),new Vector3(.07f,.085f,.004f),ink,PrimitiveType.Sphere);parts.Part("Photograph coat silhouette",photo,new Vector3(0,-.055f,.027f),new Vector3(.14f,.14f,.004f),ink);
   for(int n=0;n<7;n++){var tally=parts.Part("Previous watch tally scratch",transform,new Vector3(-3.43f,1.17f,-9.5f+n*.035f),new Vector3(.002f,.08f,.008f),paper);tally.transform.localRotation=Quaternion.Euler(n==4?35:0,0,0);}
   var crate=M2StationParts.Root("Wall stowed supply crate",transform,new Vector3(3.0f,.2f,-10.3f));parts.Part("Slatted crate",crate,Vector3.zero,new Vector3(.50f,.40f,.45f),Resources.Load<Material>("VisualMaterials/Wood"));foreach(float y in new[]{-.12f,.12f})parts.Part("Crate iron band",crate,new Vector3(0,y,-.23f),new Vector3(.52f,.025f,.008f),parts.Metal);
   var coil=new GameObject("Coiled rope on supply crate");coil.transform.SetParent(transform,false);coil.transform.position=new Vector3(3,.43f,-10.3f);ropeMesh=new Mesh{name="Original low poly rope coil"};var rv=new List<Vector3>();var rn=new List<Vector3>();var rt=new List<int>();for(int ring=0;ring<4;ring++)for(int a=0;a<24;a++)for(int b=0;b<6;b++){float u=a*Mathf.PI*2/24,v=b*Mathf.PI*2/6,r=.06f+ring*.035f;var normal=new Vector3(Mathf.Cos(u)*Mathf.Cos(v),Mathf.Sin(v),Mathf.Sin(u)*Mathf.Cos(v));rv.Add(new Vector3(Mathf.Cos(u)*r,0,Mathf.Sin(u)*r)+normal*.012f);rn.Add(normal);int i=ring*144+a*6+b,j=ring*144+((a+1)%24)*6+b,k=ring*144+a*6+(b+1)%6,l=ring*144+((a+1)%24)*6+(b+1)%6;rt.AddRange(new[]{i,j,k,k,j,l});}ropeMesh.SetVertices(rv);ropeMesh.SetNormals(rn);ropeMesh.SetTriangles(rt,0);ropeMesh.RecalculateBounds();coil.AddComponent<MeshFilter>().sharedMesh=ropeMesh;coil.AddComponent<MeshRenderer>().sharedMaterial=paper;
   var lantern=M2StationParts.Root("Dropped unlit keeper lantern",transform,new Vector3(3.1f,.12f,-9));lantern.localRotation=Quaternion.Euler(0,15,70);parts.Part("Lantern foot",lantern,Vector3.zero,new Vector3(.14f,.018f,.14f),parts.Brass,PrimitiveType.Cylinder);parts.Part("Lantern cold glass",lantern,new Vector3(0,.10f,0),new Vector3(.09f,.17f,.09f),glass,PrimitiveType.Cylinder);parts.Part("Lantern cap",lantern,new Vector3(0,.20f,0),new Vector3(.14f,.02f,.14f),parts.Brass,PrimitiveType.Cylinder);foreach(float x in new[]{-.06f,.06f})parts.Part("Lantern frame",lantern,new Vector3(x,.1f,0),new Vector3(.012f,.20f,.012f),parts.Brass);
   var stove=M2StationParts.Root("Old stove and kettle",transform,new Vector3(3.02f,.37f,-7.3f));parts.Part("Small iron stove",stove,Vector3.zero,new Vector3(.40f,.70f,.38f),parts.Dark);parts.Part("Kettle body",stove,new Vector3(0,.45f,0),new Vector3(.24f,.20f,.22f),parts.Metal,PrimitiveType.Sphere);parts.Part("Kettle spout",stove,new Vector3(.14f,.46f,0),new Vector3(.12f,.045f,.045f),parts.Metal);
  }
  Material Mat(string name,Color colour){var m=new Material(Resources.Load<Material>("VisualMaterials/Wood")){name=name};m.SetTexture("_BaseMap",null);m.SetTexture("_BumpMap",null);m.DisableKeyword("_NORMALMAP");m.SetColor("_BaseColor",colour);owned.Add(m);return m;}
  void LateUpdate(){if(core){block.Clear();block.SetColor("_BaseColor",new Color(.9f,.55f,.2f));block.SetColor("_EmissionColor",watch.State.BeaconShining?new Color(1.2f,.65f,.18f):Color.black);core.SetPropertyBlock(block);}}
  void OnDestroy(){if(ropeMesh)Destroy(ropeMesh);foreach(var m in owned)if(m)Destroy(m);}
 }
}
